<?php
namespace Tests;
use App\Services\{SalonStore,Settings,GroupMinimum,Connections,Tenant};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{DB,Artisan,Hash,Http,Mail};
final class ComfortTest extends TestCase
{
 private string $path;
 public function createApplication(){$app=require __DIR__.'/../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');$this->path=storage_path('framework/comfort-'.bin2hex(random_bytes(8)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform','raero.admin_password_hash'=>Hash::make('test-password-123')]);Artisan::call('migrate',['--force'=>true]);foreach(['calendar_tasks','calendar_connections','media_assets','mail_templates','salon_state','deliveries','guest_accounts','providers'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);Http::preventStrayRequests();$this->admin();}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();Time::setTestNow();foreach(glob($this->path.'*') as $p)unlink($p);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('t',40)])->withHeader('X-CSRF-TOKEN',str_repeat('t',40));}
 private function clock($at):void{Time::setTestNow($at);\Carbon\Carbon::setTestNow($at);}
 private function book(array $v=[]):array{return array_replace(['name'=>'Vendég','phone'=>'06301234567','email'=>'guest@example.com','services'=>['cut'],'staff'=>'anna','start'=>'2035-03-12T09:00:00Z'],$v);}
 private function group(int $minimum=3,int $capacity=3,int $lead=60):array{app(SalonStore::class)->mutate(function(&$s){$s['settings']['advancedBookingEnabled']=true;$s['services'][0]['bookingMode']='group';$s['services'][0]['capacity']=5;$s['settings']['providerEmail']='owner@example.com';});return $this->postJson('/api/group-sessions',['serviceId'=>'cut','staff'=>'anna','start'=>Time::now()->addDay()->setTime(12,0)->utc()->toISOString(),'capacity'=>$capacity,'minimumParticipants'=>$minimum,'minimumLeadMinutes'=>$lead])->assertCreated()->json();}
 private function member(array $g,int $n=0):array{return $this->postJson('/api/bookings',$this->book(['name'=>'Vendég '.$n,'phone'=>'0630123456'.$n,'email'=>'guest'.$n.'@example.com','start'=>$g['start']]))->assertCreated()->json();}
 public function test_next_free_day_is_nearest_to_today_and_does_not_select_a_time():void{$this->clock('2035-03-12T12:00:00+01:00');app(SalonStore::class)->mutate(function(&$s){$s['availability']['overrides'][]=['date'=>'2035-03-12','closed'=>true,'openingTime'=>'08:00','closingTime'=>'20:00'];});$this->withSession(['admin'=>false]);$r=$this->getJson('/api/slots/next?services=cut&staff=anna')->assertOk()->assertJsonPath('date','2035-03-13')->assertJsonMissingPath('clients');$this->assertNotEmpty($r->json('slots'));$this->getJson('/api/slots/next?services=unknown&staff=anna')->assertOk()->assertJsonPath('date',null);}
 public function test_group_search_can_find_a_published_class_beyond_a_year():void{$this->clock('2026-11-07T09:00:00+01:00');app(SalonStore::class)->mutate(function(&$s){$s['settings']['advancedBookingEnabled']=true;$s['services'][0]['bookingMode']='group';});$this->postJson('/api/group-sessions',['serviceId'=>'cut','staff'=>'anna','start'=>'2035-03-12T09:00:00Z','capacity'=>3])->assertCreated();$this->withSession(['admin'=>false]);$this->getJson('/api/slots/next?services=cut&staff=anna')->assertOk()->assertJsonPath('date','2035-03-12');}
 public function test_minimum_deadline_cancels_once_and_queues_guests_and_provider():void{$g=$this->group();$this->member($g,1);$this->member($g,2);$this->clock(GroupMinimum::deadline($g));$result=GroupMinimum::run();$this->assertSame(1,$result['missed']);$s=app(SalonStore::class)->read();$this->assertSame('missed',$s['groupSessions'][0]['status']);foreach($s['bookings'] as $b){$this->assertSame('cancelled',$b['status']);$this->assertSame('group_minimum',$b['cancellationReason']);}$this->assertSame(3,DB::table('deliveries')->count());GroupMinimum::run();$this->assertSame(3,DB::table('deliveries')->count());$this->getJson('/api/public')->assertJsonCount(0,'groupSessions');}
 public function test_confirmed_minimum_is_frozen_at_deadline_and_later_dropout_does_not_cancel():void{$g=$this->group(2);$a=$this->member($g,1);$this->member($g,2);$this->clock(GroupMinimum::deadline($g));GroupMinimum::run();$this->patchJson('/api/bookings/'.$a['id'],['status'=>'cancelled'])->assertOk();$s=app(SalonStore::class)->read();$this->assertFalse($s['groupSessions'][0]['cancelled']);$this->assertNotEmpty($s['groupSessions'][0]['minimumCheckedAt']);$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3,'minimumParticipants'=>3])->assertUnprocessable();}
 public function test_pending_participants_do_not_satisfy_confirmed_minimum():void{$g=$this->group(2);$this->member($g,1);$b=$this->member($g,2);$this->patchJson('/api/bookings/'.$b['id'],['status'=>'pending'])->assertOk();$this->clock(GroupMinimum::deadline($g));GroupMinimum::run();$this->assertSame('missed',app(SalonStore::class)->read()['groupSessions'][0]['status']);}
 public function test_late_signup_cannot_rescue_a_class_after_deadline():void{$g=$this->group(2);$this->member($g,1);$this->clock(GroupMinimum::deadline($g)->addSecond());$this->postJson('/api/bookings',$this->book(['start'=>$g['start']]))->assertUnprocessable();$this->getJson('/api/public')->assertJsonCount(0,'groupSessions');}
 public function test_provider_can_mark_class_missed_and_notifications_are_real_mailables():void{$g=$this->group(0);$this->member($g,1);app(Connections::class)->save(['smtp_host'=>'smtp.example.invalid','smtp_port'=>587,'mail_from'=>'sender@example.com']);Mail::fake();$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3,'status'=>'missed'])->assertCreated()->assertJsonPath('status','missed');$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3,'status'=>'missed'])->assertCreated();$result=app(\App\Services\Notifications::class)->run();$this->assertSame(2,$result['sent']);Mail::assertSent(\App\Mail\NotificationMail::class,2);}
 public function test_minimum_settings_are_validated():void{app(SalonStore::class)->mutate(function(&$s){$s['settings']['advancedBookingEnabled']=true;$s['services'][0]['bookingMode']='group';});$data=['serviceId'=>'cut','staff'=>'anna','start'=>Time::now()->addHours(2)->utc()->toISOString(),'capacity'=>2,'minimumParticipants'=>3,'minimumLeadMinutes'=>60];$this->postJson('/api/group-sessions',$data)->assertUnprocessable();$this->postJson('/api/group-sessions',array_replace($data,['minimumParticipants'=>2,'minimumLeadMinutes'=>180]))->assertUnprocessable();}
 public function test_new_client_contact_validation_and_hungarian_normalization():void{$this->postJson('/api/clients',['name'=>'Név','phone'=>'123','email'=>''])->assertUnprocessable();$this->postJson('/api/clients',['name'=>'Név','phone'=>'','email'=>'wrong'])->assertUnprocessable();$this->postJson('/api/clients',['name'=>'Név'])->assertUnprocessable();$this->postJson('/api/clients',['name'=>'Név','phone'=>'+36 30 123-4567','email'=>'Person@Example.com'])->assertCreated()->assertJsonPath('phone','06301234567')->assertJsonPath('email','person@example.com');$this->postJson('/api/clients?provider=2',['name'=>'Más','email'=>'other@example.com'])->assertForbidden();}
 public function test_due_rows_are_not_paid_money_and_disappear_when_settled_or_cancelled():void{$b=$this->postJson('/api/bookings',$this->book())->assertCreated()->json();app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']=Time::now()->subMinutes(30)->utc()->toISOString();$s['bookings'][0]['status']='confirmed';});$this->getJson('/api/state')->assertJsonCount(0,'payments')->assertJsonPath('paymentDues.0.amount',8500);$this->postJson('/api/payments',['bookingId'=>$b['id'],'amount'=>1000,'method'=>'cash','paidAt'=>Time::now()->toISOString()])->assertCreated();$this->getJson('/api/state')->assertJsonPath('paymentDues.0.amount',7500)->assertJsonCount(1,'payments');$this->patchJson('/api/bookings/'.$b['id'],['status'=>'cancelled'])->assertOk();$this->getJson('/api/state')->assertJsonCount(0,'paymentDues')->assertJsonCount(1,'payments');}
 public function test_due_defaults_can_be_disabled_without_creating_or_deleting_payments():void{$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['paymentDefaults'=>['enabled'=>false,'method'=>'transfer','note'=>'Banki rendezés']])])->assertOk();$this->getJson('/api/state')->assertJsonPath('settings.paymentDefaults.method','transfer')->assertJsonCount(0,'payments')->assertJsonCount(0,'paymentDues');}
 public function test_cancelled_booking_can_be_restored_only_if_slot_is_still_free():void{$b=$this->postJson('/api/bookings',$this->book())->assertCreated()->json();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'cancelled'])->assertOk();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertOk();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'pending'])->assertOk();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'cancelled'])->assertOk();$this->postJson('/api/bookings',$this->book())->assertCreated();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertUnprocessable();}
 public function test_cancelled_pass_booking_rechecks_and_reserves_the_returned_visit_once():void{$client=$this->postJson('/api/clients',['name'=>'Vendég','phone'=>'06301234567','email'=>'guest@example.com'])->assertCreated()->json();$p=$this->postJson('/api/passes',['name'=>'Bérlet','price'=>8000,'visits'=>1,'days'=>3650,'services'=>['cut'],'active'=>true])->assertCreated()->json();$pass=$this->postJson('/api/client-passes',['clientId'=>$client['id'],'passId'=>$p['id']])->assertCreated()->json();$b=$this->postJson('/api/bookings',$this->book(['clientId'=>$client['id'],'passId'=>$pass['id']]))->assertCreated()->json();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'cancelled'])->assertOk();$this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertOk();$this->assertSame(0,app(SalonStore::class)->read()['clientPasses'][0]['remaining']);$this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertOk();$this->assertSame(0,app(SalonStore::class)->read()['clientPasses'][0]['remaining']);}
 public function test_nearest_day_search_skips_long_holiday_blocks_and_respects_embed_origin():void{$this->clock('2035-03-12T12:00:00+01:00');app(SalonStore::class)->mutate(function(&$s){$s['settings']['embedOrigins']=['https://salon.example.com'];$s['availability']['blocks'][]=['id'=>'holiday','label'=>'Szabadság','fromDate'=>'2035-03-12','toDate'=>'2035-06-30','allDay'=>true,'staffId'=>null];});$this->withHeader('Origin','https://salon.example.com')->getJson('/api/slots/next?services=cut&staff=anna')->assertOk()->assertJsonPath('date','2035-07-01')->assertHeader('Access-Control-Allow-Origin','https://salon.example.com');$this->getJson('/api/state')->assertHeaderMissing('Access-Control-Allow-Origin');}
 public function test_minimum_can_be_enabled_on_previously_unrestricted_class_with_new_future_deadline():void{$g=$this->group(0);$this->clock(Time::parse($g['start'])->subMinutes(45));$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3,'minimumParticipants'=>2,'minimumLeadMinutes'=>30])->assertCreated()->assertJsonPath('minimumParticipants',2);}
 public function test_cancelled_coupon_booking_cannot_bypass_reused_coupon_limit_when_restored():void{$s=app(SalonStore::class)->read();$s['coupons']=[['id'=>'limited','name'=>'Kupon','code'=>'LIMIT','active'=>true,'public'=>false,'firstVisit'=>false,'startsAt'=>Time::now()->subDay()->toISOString(),'endsAt'=>Time::now()->addYears(20)->toISOString(),'services'=>['cut'],'type'=>'fixed','value'=>1000,'limit'=>1,'perClient'=>2]];DB::table('salon_state')->where('id',1)->update(['data'=>json_encode($s)]);$a=$this->postJson('/api/bookings',$this->book(['coupon'=>'LIMIT']))->assertCreated()->json();$this->patchJson('/api/bookings/'.$a['id'],['status'=>'cancelled'])->assertOk();$this->postJson('/api/bookings',$this->book(['coupon'=>'LIMIT','start'=>'2035-03-13T09:00:00Z']))->assertCreated();$this->patchJson('/api/bookings/'.$a['id'],['status'=>'confirmed'])->assertUnprocessable();}

}
